style.css:
@-moz-document domain("web.whatsapp.com") {
/* swap any of these values to retune the whole look */
  :root {
    --my-pink: #ffd1e3;
    --my-green: #d4f5de;
    --my-sidebar: #ece0ff;
    --my-header: #f8d9ff;
    --my-wallpaper: #fff4f8;
    --my-text: #5b4b6b;
    --my-font: "Quicksand", "Nunito", "Varela Round", "Chalkboard SE", "Marker Felt", "Segoe UI", sans-serif;
  }

  /* WhatsApp's own color variables: bubbles and panels */
  :root, body, .web, #app {
    --outgoing-background: var(--my-pink) !important;
    --incoming-background: var(--my-green) !important;
    --conversation-panel-background: var(--my-wallpaper) !important;
    --background-default: var(--my-sidebar) !important;
    --panel-header-background: var(--my-header) !important;
    --app-background: #f6e9ff !important;
  }

  /* font everywhere */
  #app, #app * {
    font-family: var(--my-font) !important;
  }

  /* contacts sidebar */
  #side {
    background: var(--my-sidebar) !important;
  }

  /* chat wallpaper: tiny hearts, stars and bows (kept faint so text stays readable) */
  #main,
  #main [data-testid="conversation-panel-wrapper"] {
    background-color: var(--my-wallpaper) !important;
    background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><text x='14' y='34' font-size='20' opacity='.55'>?</text><text x='96' y='60' font-size='16' opacity='.5'>⭐</text><text x='40' y='110' font-size='18' opacity='.5'>?</text><text x='116' y='138' font-size='20' opacity='.55'>?</text><text x='80' y='20' font-size='12' opacity='.45'>✨</text></svg>") !important;
    background-size: 160px 160px !important;
  }

  /* message text color */
  .message-in, .message-out {
    color: var(--my-text) !important;
  }
}
